Item.method_code:
const topWnd = aras.getMostTopWindowWithAras();
const cuiCommands = topWnd.cuiCommands;
return topWnd.ArasModules.metadata.itemType.getItemType(inArgs.referencedTypeName)
    .then(itemTypeDef => {
        const command = cuiCommands.commandFactory('NewItem', {
            'itemTypeName': inArgs.referencedTypeName,
            'itemType': itemTypeDef,
            'location': 'ItemView'
        });
        return command.execute();
    })
    .then(boundItemNd => {
        const boundItem = aras.newIOMItem();
        boundItem.dom = boundItemNd.ownerDocument;
        boundItem.node = boundItemNd;
        const uiUtils = new window.CMF.UI.Utils();

        return new Promise(function(resolve) {
        	uiUtils.showEditorTearOff(boundItem, function() {
        		resolve(boundItem.getID());
        	});
        });
    });
